class Solution:
 def pickGifts(self, gifts, k):
  import heapq, math
  h=[-x for x in gifts]; heapq.heapify(h)
  for _ in range(k):
   x=-heapq.heappop(h); heapq.heappush(h,-math.isqrt(x))
  return -sum(h)

class Solution:
 def findTheArrayConcVal(self, nums):
  i=0; j=len(nums)-1; total=0
  while i<j:
   total+=int(str(nums[i])+str(nums[j])); i+=1; j-=1
  if i==j: total+=nums[i]
  return total

class Solution:
 def mergeArrays(self, nums1, nums2):
  d={}
  for i,v in nums1+nums2: d[i]=d.get(i,0)+v
  return [[i,d[i]] for i in sorted(d)]

class Solution:
 def leftRightDifference(self, nums):
  right=sum(nums); left=0; out=[]
  for x in nums:
   right-=x; out.append(abs(left-right)); left+=x
  return out

class Solution:
 def passThePillow(self, n, time):
  q,r=divmod(time,n-1)
  return r+1 if q%2==0 else n-r

class Solution:
 def kItemsWithMaximumSum(self, numOnes, numZeros, numNegOnes, k):
  return min(k,numOnes)-max(0,k-numOnes-numZeros)

class Solution:
 def minNumber(self, nums1, nums2):
  common=set(nums1)&set(nums2)
  if common: return min(common)
  a=min(nums1); b=min(nums2)
  return min(10*a+b,10*b+a)

class Solution:
 def findMatrix(self, nums):
  rows=[]
  for x in nums:
   for row in rows:
    if x not in row: row.append(x); break
   else: rows.append([x])
  return rows

class Solution:
 def diagonalPrime(self, nums):
  def prime(x):
   if x<2: return False
   d=2
   while d*d<=x:
    if x%d==0: return False
    d+=1
   return True
  n=len(nums); best=0
  for i in range(n):
   if prime(nums[i][i]): best=max(best,nums[i][i])
   if prime(nums[i][n-1-i]): best=max(best,nums[i][n-1-i])
  return best
